INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2058FUG', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The graphs of $y = x^2 - 6x + 2$ and $y = 3x - 16$ intersect at two points. What is one of the intersection points?', NULL, $lyceon_json$[{"key":"A","text":"$(3, -7)$"},{"key":"B","text":"$(3, 7)$"},{"key":"C","text":"$(6, -2)$"},{"key":"D","text":"$(6, 16)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $(3, -7)$. Setting $x^2 - 6x + 2 = 3x - 16$ and simplifying yields $x^2 - 9x + 18 = 0$, which factors as $(x - 3)(x - 6) = 0$. When $x = 3$, $y = 3(3) - 16 = -7$, giving the point $(3, -7)$. When $x = 6$, $y = 3(6) - 16 = 2$, giving $(6, 2)$. The point $(3, 7)$ uses the correct $x$-value but has the wrong sign for $y$. The point $(6, -2)$ substitutes $x = 6$ into the wrong expression. The point $(6, 16)$ miscomputes $y$ by evaluating $3(6) - 16$ incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20M4USA', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution of $x^2 + 3x - 54 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$6$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $6$. Factoring the quadratic gives $(x + 9)(x - 6) = 0$, so $x = -9$ or $x = 6$. The positive solution is $6$. The value $-9$ is the negative root, not the positive one. The value $-6$ comes from confusing the sign of the positive root''s factor. The value $9$ results from taking the absolute value of the negative root rather than solving correctly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20MNYBF', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $h$ is defined by $h(x) = ax + b$, where $a > 0$. If $h(h(2)) = 34$ and $h(h(5)) = 61$, what is the value of $h(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$-8$"},{"key":"C","text":"$3$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $4$. Since $h(x) = ax + b$, the composition is $h(h(x)) = a(ax + b) + b = a^2x + ab + b$. From the given conditions: $h(h(2)) = 2a^2 + ab + b = 34$ and $h(h(5)) = 5a^2 + ab + b = 61$. Subtracting the first equation from the second gives $3a^2 = 27$, so $a^2 = 9$. Since $a > 0$, we have $a = 3$. Substituting back: $2(9) + 3b + b = 34$, which gives $18 + 4b = 34$, so $4b = 16$ and $b = 4$. Therefore $h(0) = a(0) + b = 4$. The value $-8$ results from using $a = -3$ (ignoring the constraint $a > 0$), which gives $b = -8$. The value $3$ comes from confusing the value of $a$ with the value of $b$. The value $7$ results from a sign error in the substitution step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21SXC1L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set consists of $11$ values. The mean of the data set is $47$ and the median is $43$. If the value $43$ is removed from the data set, which of the following must be true about the remaining $10$ values?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the median stays the same."},{"key":"B","text":"The mean increases and the median could change."},{"key":"C","text":"The mean stays the same and the median increases."},{"key":"D","text":"Both the mean and the median decrease."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is that the mean increases and the median could change. The sum of all $11$ values is $47 \\times 11 = 517$. Removing $43$ gives a sum of $474$ over $10$ values, so the new mean is $\\frac{474}{10} = 47.4$, which is greater than $47$. Since $43$ is below the original mean, removing it raises the mean. For the median, the original median was the 6th value in sorted order. After removing one instance of $43$, the new median is the average of the 5th and 6th values among the remaining $10$, which could shift depending on the surrounding values. The claim that the mean decreases is incorrect because removing a below-mean value raises the mean. The claim that the mean stays the same ignores the effect of removing a value different from the mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM222N63O', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'grid_in', E'If $-3x + 14 \\leq 5$, what is the least value of $x$ that satisfies this inequality?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Solving $-3x + 14 \\leq 5$, subtract $14$ from both sides to get $-3x \\leq -9$. Dividing both sides by $-3$ requires reversing the inequality sign, giving $x \\geq 3$. The least value of $x$ satisfying this inequality is $3$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22XG5VF', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A movie theater sold a total of $143$ tickets for a showing. Adult tickets cost \\$11 each and child tickets cost \\$6 each. If the total ticket revenue was \\$1,243, how many adult tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$66$"},{"key":"B","text":"$77$"},{"key":"C","text":"$85$"},{"key":"D","text":"$113$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $77$. Let $a$ represent adult tickets and $c$ represent child tickets. The system is $a + c = 143$ and $11a + 6c = 1{,}243$. From the first equation, $c = 143 - a$. Substituting into the second: $11a + 6(143 - a) = 1{,}243$, which gives $11a + 858 - 6a = 1{,}243$, so $5a = 385$ and $a = 77$. The value $66$ is the number of child tickets ($143 - 77 = 66$), not adult tickets. The value $85$ results from a subtraction error when computing $1{,}243 - 858$. The value $113$ comes from dividing the total revenue by the adult ticket price alone ($1{,}243 \\div 11 \\approx 113$), ignoring the presence of child tickets.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24LE7P5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $17$ meters and a width of $9$ meters. What is the area, in square meters, of the rectangle?', NULL, $lyceon_json$[{"key":"A","text":"$26$"},{"key":"B","text":"$52$"},{"key":"C","text":"$153$"},{"key":"D","text":"$163$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $153$. The area of a rectangle is length times width: $17 \\times 9 = 153$ square meters. The value $26$ is the sum $17 + 9$, which confuses addition with multiplication. The value $52$ is the perimeter $2(17 + 9) = 52$, which answers a different question. The value $163$ results from an arithmetic error when multiplying $17 \\times 9$.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24WZI8F', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $\\frac{45m^6}{9m^2}$?', NULL, $lyceon_json$[{"key":"A","text":"$5m^4$"},{"key":"B","text":"$5m^8$"},{"key":"C","text":"$36m^4$"},{"key":"D","text":"$5m^3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $5m^4$. Dividing the coefficients gives $\\frac{45}{9} = 5$, and applying the quotient rule for exponents gives $m^{6-2} = m^4$. The result $5m^8$ comes from adding the exponents ($6 + 2 = 8$) instead of subtracting them. The result $36m^4$ comes from subtracting the coefficients ($45 - 9 = 36$) instead of dividing. The result $5m^3$ comes from dividing the exponents ($\\frac{6}{2} = 3$) instead of subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM250RRRQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ in the equation $5(x + 3) - 2(x - 4) = 38$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Distribute on the left side: $5x + 15 - 2x + 8 = 38$. Combine like terms: $3x + 23 = 38$. Subtract $23$ from both sides: $3x = 15$. Divide by $3$: $x = 5$. A common error is distributing the negative sign incorrectly to get $-2x - 8$ instead of $-2x + 8$, which would yield $3x + 7 = 38$ and $x = \\frac{31}{3}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25BYQSZ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $(x^2 - 7x + 10)(x + 3) - (x^2 - 4)(x - 5)$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^3 - 9x^2 - 15x + 50$"},{"key":"B","text":"$x^2 - 7x + 10$"},{"key":"C","text":"$-x^2 + 7x - 10$"},{"key":"D","text":"$-7x + 10$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $x^2 - 7x + 10$. Expanding the first product: $(x^2 - 7x + 10)(x + 3) = x^3 + 3x^2 - 7x^2 - 21x + 10x + 30 = x^3 - 4x^2 - 11x + 30$. Expanding the second product: $(x^2 - 4)(x - 5) = x^3 - 5x^2 - 4x + 20$. Subtracting gives $(x^3 - 4x^2 - 11x + 30) - (x^3 - 5x^2 - 4x + 20) = x^2 - 7x + 10$. The result $2x^3 - 9x^2 - 15x + 50$ comes from adding the two expanded products instead of subtracting, reflecting incomplete reasoning about the subtraction. The result $-x^2 + 7x - 10$ reverses all signs in the correct answer, a sign error from subtracting in the wrong order. The result $-7x + 10$ drops the $x^2$ term during the subtraction step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26GOF5Q', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The system of equations $x^2 + y^2 = 74$ and $x - y = 2$ has two solutions. What is the positive value of $x$ in the solution where $y$ is also positive?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'From $x - y = 2$, we get $x = y + 2$. Substituting into $x^2 + y^2 = 74$ gives $(y + 2)^2 + y^2 = 74$, which expands to $y^2 + 4y + 4 + y^2 = 74$, or $2y^2 + 4y - 70 = 0$. Dividing by $2$: $y^2 + 2y - 35 = 0$, which factors as $(y + 7)(y - 5) = 0$. So $y = -7$ or $y = 5$. When $y = 5$, $x = 7$, and both are positive. When $y = -7$, $x = -5$, which does not satisfy the positive condition. The answer is $7$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26TMIC2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For which value of $c$ does the system $y = x^2 + 7x + c$ and $y = 2x + 3$ have no real solutions?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$9$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $11$. Setting $x^2 + 7x + c = 2x + 3$ gives $x^2 + 5x + (c - 3) = 0$. For no real solutions, the discriminant must be negative: $25 - 4(c - 3) < 0$, so $25 - 4c + 12 < 0$, meaning $37 - 4c < 0$ and $c > \\frac{37}{4} = 9.25$. Among the choices, only $11 > 9.25$. The value $9$ is close to the boundary but gives discriminant $25 - 4(6) = 1 > 0$, which still yields two solutions. The values $5$ and $7$ both produce positive discriminants, meaning the system has real solutions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2893QTG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $JKL$, angle $L$ is the right angle, $JK = 29$, and $KL = 20$. What is $\\sin(J)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{20}{29}$"},{"key":"B","text":"$\\frac{21}{29}$"},{"key":"C","text":"$\\frac{20}{21}$"},{"key":"D","text":"$\\frac{29}{20}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{20}{29}$. In right triangle $JKL$ with the right angle at $L$, the hypotenuse is $JK = 29$. The side opposite angle $J$ is $KL = 20$. Therefore $\\sin(J) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{20}{29}$. The value $\\frac{21}{29}$ uses the adjacent side $JL = \\sqrt{29^2 - 20^2} = 21$ instead of the opposite side, which gives $\\cos(J)$ rather than $\\sin(J)$. The value $\\frac{20}{21}$ is $\\tan(J)$, using opposite over adjacent instead of opposite over hypotenuse. The value $\\frac{29}{20}$ is the reciprocal $\\csc(J)$, inverting the sine ratio.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28RL0GH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A bag contains $5$ red marbles, $8$ blue marbles, and $3$ green marbles. Two marbles are drawn at random without replacement. Given that the first marble drawn is blue, what is the probability that the second marble drawn is also blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{8}{16}$"},{"key":"B","text":"$\\frac{7}{16}$"},{"key":"C","text":"$\\frac{7}{15}$"},{"key":"D","text":"$\\frac{8}{15}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $\\frac{7}{15}$. The total number of marbles is $5 + 8 + 3 = 16$. Given that the first marble drawn is blue, there are $7$ blue marbles remaining out of $15$ total marbles, so the probability is $\\frac{7}{15}$. The answer $\\frac{8}{16}$ fails to account for the removal of the first blue marble, treating the draws as if they were independent. The answer $\\frac{7}{16}$ correctly reduces the blue count but does not reduce the total number of marbles. The answer $\\frac{8}{15}$ reduces the total but not the count of blue marbles.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2937HVI', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $9x + 17 > 80$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $8$. Solving $9x + 17 > 80$ requires subtracting $17$ from both sides to obtain $9x > 63$, then dividing both sides by $9$ to get $x > 7$. Substituting $8$ yields $9(8) + 17 = 89$, which is greater than $80$. The value $7$ produces $9(7) + 17 = 80$, which is not strictly greater than $80$ and therefore does not satisfy the inequality. The values $6$ and $5$ yield $71$ and $62$ respectively, both less than $80$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM299T7DH', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'If $4x - 3y = 29$ and $2x + 3y = 7$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Adding the two equations eliminates $y$: $(4x - 3y) + (2x + 3y) = 29 + 7$, which simplifies to $6x = 36$, so $x = 6$. This can be verified by substituting back: $4(6) - 3y = 29$ gives $y = -\\frac{5}{3}$, and $2(6) + 3\\left(-\\frac{5}{3}\\right) = 12 - 5 = 7$, confirming the solution.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29W8O8D', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $25x^2 - 121$?', NULL, $lyceon_json$[{"key":"A","text":"$(5x - 11)(5x + 11)$"},{"key":"B","text":"$(5x - 11)^2$"},{"key":"C","text":"$(25x - 11)(x + 11)$"},{"key":"D","text":"$5(x - 11)(x + 11)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $(5x - 11)(5x + 11)$. The expression $25x^2 - 121$ is a difference of two squares, since $25x^2 = (5x)^2$ and $121 = 11^2$. Applying the identity $a^2 - b^2 = (a - b)(a + b)$ gives $(5x - 11)(5x + 11)$. The expression $(5x - 11)^2$ expands to $25x^2 - 110x + 121$, which includes a middle term and the wrong sign on the constant, reflecting confusion between a perfect square trinomial and a difference of squares. The expression $(25x - 11)(x + 11)$ fails to take the square root of $25x^2$, and expands to $25x^2 + 264x - 121$. The expression $5(x - 11)(x + 11)$ incorrectly factors out $5$ from $25x^2$ as though $25x^2 = 5 \\cdot x^2$, and expands to $5x^2 - 605$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AB1AKJ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A tank contains $200$ gallons of water. Water drains from the tank at a constant rate of $13$ gallons per minute. After how many minutes will the tank contain exactly $57$ gallons?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Let $t$ represent the number of minutes. The amount of water remaining is modeled by $f(t) = 200 - 13t$. Setting $f(t) = 57$: $200 - 13t = 57$. Subtract $200$ from both sides: $-13t = -143$. Divide by $-13$: $t = 11$. Verification: $200 - 13(11) = 200 - 143 = 57$. A common error is dividing $57$ by $13$ instead of first computing $200 - 57 = 143$ and then dividing by $13$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CNWNXG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $7$ cups of flour to make $42$ muffins. How many cups of flour are needed to make $18$ muffins?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$6$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $3$. The ratio of flour to muffins is $\\frac{7}{42} = \\frac{1}{6}$ cup per muffin. For $18$ muffins: $\\frac{1}{6} \\times 18 = 3$ cups. The answer $6$ results from computing $\\frac{42}{7}$ without applying the ratio to the target quantity. The answer $2$ comes from an arithmetic slip such as dividing $18$ by $7$ and rounding down. The answer $4$ reflects a conceptual error in setting up the proportion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DSQWPB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers wanted to determine whether a new fertilizer increases tomato yield. They assigned $60$ tomato plants to two groups: Group A received the new fertilizer and Group B received no fertilizer. The plants in Group A were all located in a greenhouse, while the plants in Group B were all located outdoors. Group A had a higher average yield than Group B. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer causes higher tomato yield."},{"key":"B","text":"The difference in yield may be due to the growing environment rather than the fertilizer."},{"key":"C","text":"The study proves that greenhouses are better than outdoor growing for tomatoes."},{"key":"D","text":"No conclusion can be drawn because $60$ plants is too small a sample."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is that the difference in yield may be due to the growing environment rather than the fertilizer. Because the fertilizer treatment and the growing location are confounded — every plant receiving fertilizer is also in a greenhouse — it is impossible to attribute the yield difference solely to the fertilizer. The claim that the fertilizer causes higher yield ignores the confounding variable of growing environment. The claim that the study proves greenhouses are better also goes beyond what the data can support, since the greenhouse group simultaneously received fertilizer. The claim that no conclusion can be drawn due to sample size misidentifies the problem; the core issue is confounding, not sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EKOQH9', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'The expression $\\frac{x^2 - 23x + 132}{x - 11}$ can be written in the form $x + k$, where $k$ is a constant and $x \\neq 11$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-12', ARRAY['-12'], E'The correct answer is $-12$. To simplify $\\frac{x^2 - 23x + 132}{x - 11}$, factor the numerator. We need two numbers that multiply to $132$ and add to $-23$. Since $(-11)(-12) = 132$ and $-11 + (-12) = -23$, the numerator factors as $(x - 11)(x - 12)$. Dividing by $(x - 11)$ gives $x - 12$, so $k = -12$. A common error is to use the wrong sign when identifying the factors, arriving at $k = 12$ instead of $k = -12$. Another error is to stop after identifying $11$ as a root of the denominator and conclude $k = -11$, which confuses the divisor with the quotient remainder.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EOLLBF', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f(x) = 7x - 13$ models the total cost, in dollars, of purchasing $x$ items. What does the number $7$ represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The cost per item"},{"key":"B","text":"The total number of items"},{"key":"C","text":"The initial fixed cost"},{"key":"D","text":"The total cost of all items"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that $7$ represents the cost per item. In the linear function $f(x) = 7x - 13$, the coefficient of $x$ is the rate of change, meaning each additional item adds $7$ dollars to the total cost. The initial fixed cost is represented by the constant $-13$, not by $7$. The total number of items is the input variable $x$, not the coefficient. The total cost of all items depends on the number purchased and is given by the full expression $f(x)$, not by the coefficient alone.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EUL15S', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A student scored $73$, $81$, and $68$ on the first three tests in a class. The student needs an average of at least $78$ across all four tests. Which inequality represents the score $s$ the student needs on the fourth test?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{73 + 81 + 68 + s}{4} \\geq 78$"},{"key":"B","text":"$\\frac{73 + 81 + 68 + s}{4} > 78$"},{"key":"C","text":"$\\frac{73 + 81 + 68}{3} + s \\geq 78$"},{"key":"D","text":"$73 + 81 + 68 + s \\geq 78$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{73 + 81 + 68 + s}{4} \\geq 78$. The average of four test scores is their sum divided by $4$, and the phrase "at least $78$" translates to $\\geq 78$. The inequality using the strict symbol $>$ is incorrect because "at least" includes equality. The expression that averages only the first three scores and then adds $s$ misrepresents how a four-test average is computed. The inequality that omits division by $4$ compares the raw sum to $78$ rather than the average.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G1XC0D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A printer produces $37$ pages in $4$ minutes. At this constant rate, how many pages will the printer produce in $26$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$222$"},{"key":"B","text":"$240.5$"},{"key":"C","text":"$148$"},{"key":"D","text":"$259$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $240.5$. The rate is $\\frac{37}{4} = 9.25$ pages per minute. In $26$ minutes the printer produces $9.25 \\times 26 = 240.5$ pages. The result $222$ comes from incorrectly computing $37 \\times 6$, treating $26$ minutes as exactly $6$ intervals of $4$ minutes while ignoring the remaining $2$ minutes. The result $148$ is $37 \\times 4$, an intermediate product that does not answer the question. The result $259$ arises from a setup error such as miscomputing $37 \\times 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HSSLZQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A jacket originally priced at $\\$145$ is marked down by $22\\%$. A sales tax of $7\\%$ is then applied to the discounted price. What is the total cost of the jacket, to the nearest cent?', NULL, $lyceon_json$[{"key":"A","text":"$\\$113.10$"},{"key":"B","text":"$\\$121.02$"},{"key":"C","text":"$\\$123.25$"},{"key":"D","text":"$\\$118.90$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $\\$121.02$. The discounted price is $145 \\times 0.78 = 113.10$. Applying $7\\%$ tax gives $113.10 \\times 1.07 = 121.017$, which rounds to $\\$121.02$. The result $\\$113.10$ stops after computing the discount without applying tax. The result $\\$123.25$ comes from incorrectly combining the rates as a single $15\\%$ discount ($145 \\times 0.85 = 123.25$) instead of applying the discount and tax sequentially. The result $\\$118.90$ reflects an arithmetic error in the tax computation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I65QIW', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'What is the greatest integer value of $x$ that satisfies the inequality $$\\frac{3(2x - 7)}{4} + 5 \\leq \\frac{x + 11}{2}$$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $5$. Multiply every term by $4$ to clear denominators: $3(2x - 7) + 20 \\leq 2(x + 11)$. Distributing gives $6x - 21 + 20 \\leq 2x + 22$, which simplifies to $6x - 1 \\leq 2x + 22$. Subtracting $2x$ and adding $1$ to both sides yields $4x \\leq 23$, so $x \\leq \\frac{23}{4} = 5.75$. The greatest integer satisfying this is $5$. The value $6$ exceeds $5.75$ and does not satisfy the inequality. The value $23$ comes from stopping at $4x \\leq 23$ without dividing by $4$. The value $2$ results from incorrectly multiplying only the left side by $4$ while leaving the right side unchanged, leading to $5x \\leq 12$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IDINMG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $11x^3 - 4x^2 + 3x^3 + 7x^2$?', NULL, $lyceon_json$[{"key":"A","text":"$14x^3 + 3x^2$"},{"key":"B","text":"$14x^3 - 3x^2$"},{"key":"C","text":"$8x^3 + 11x^2$"},{"key":"D","text":"$14x^3 + 11x^2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $14x^3 + 3x^2$. Combining the $x^3$ terms gives $11x^3 + 3x^3 = 14x^3$, and combining the $x^2$ terms gives $-4x^2 + 7x^2 = 3x^2$. The result $14x^3 - 3x^2$ comes from subtracting the $x^2$ coefficients in the wrong order, computing $4 - 7$ instead of $-4 + 7$. The result $8x^3 + 11x^2$ arises from incorrectly adding the coefficients across different powers. The result $14x^3 + 11x^2$ adds the absolute values $4 + 7 = 11$ for the $x^2$ terms instead of using their signs.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IRRPGU', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $g$ satisfies $g(3) = 17$ and $g(11) = 49$. What is $g(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$33$"},{"key":"C","text":"$35$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $33$. The rate of change is $\\frac{49 - 17}{11 - 3} = \\frac{32}{8} = 4$. Using $g(3) = 17$: $g(x) = 4(x - 3) + 17 = 4x + 5$. Therefore $g(7) = 4(7) + 5 = 28 + 5 = 33$. The value $29$ comes from an arithmetic slip such as miscalculating the $y$-intercept. The value $35$ results from averaging $17$ and $49$ without accounting for the unequal spacing of the input values relative to $7$. The value $25$ comes from computing the slope incorrectly, for instance using $\\frac{49 - 17}{11 + 3} = \\frac{32}{14}$ and proceeding with a wrong rate of change.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J7AOJJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'An exponential function $f(x) = a \\cdot b^x$ passes through the points $(0, 5)$ and $(2, 45)$. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$9$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $3$. From the point $(0, 5)$, $f(0) = a \\cdot b^0 = a = 5$. Substituting into $f(2) = 45$ gives $5b^2 = 45$, so $b^2 = 9$ and $b = 3$ (since $b$ must be positive for an exponential function). The value $5$ confuses $a$ with $b$. The value $9$ is $b^2$, the intermediate step before taking the square root. The value $15$ comes from dividing $45$ by $3$ instead of $5$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JBJYBC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f(x) = x^3 - 12x$ is decreasing on which of the following intervals?', NULL, $lyceon_json$[{"key":"A","text":"$x < -2$"},{"key":"B","text":"$-2 < x < 2$"},{"key":"C","text":"$x > 2$"},{"key":"D","text":"$x > 0$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the interval $-2 < x < 2$. Evaluating the function at key points: $f(-3) = (-3)^3 - 12(-3) = -27 + 36 = 9$, $f(-2) = (-2)^3 - 12(-2) = -8 + 24 = 16$, $f(0) = 0$, $f(2) = (2)^3 - 12(2) = 8 - 24 = -16$, and $f(3) = (3)^3 - 12(3) = 27 - 36 = -9$. The function increases from $x = -3$ to $x = -2$ (from $9$ to $16$), decreases from $x = -2$ to $x = 2$ (from $16$ to $-16$), and increases again from $x = 2$ to $x = 3$ (from $-16$ to $-9$). Therefore the function is decreasing on the interval $-2 < x < 2$. The interval $x < -2$ includes the region where the function is increasing. The interval $0 < x < 4$ includes $x > 2$ where the function is increasing. The interval $x > 2$ is entirely in the increasing region.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L3JA9L', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $53^\\circ$ and the measure of angle $Q$ is $71^\\circ$. What is the measure, in degrees, of the exterior angle at vertex $R$?', NULL, $lyceon_json$[{"key":"A","text":"$56$"},{"key":"B","text":"$124$"},{"key":"C","text":"$126$"},{"key":"D","text":"$236$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $124$. The exterior angle of a triangle equals the sum of the two non-adjacent interior angles, so the exterior angle at $R$ is $53 + 71 = 124$ degrees. Equivalently, the interior angle at $R$ is $180 - 53 - 71 = 56$, and its supplement is $180 - 56 = 124$. The value $56$ is the interior angle at $R$, not the exterior angle. The value $126$ results from an arithmetic error when summing $53 + 71$. The value $236$ comes from incorrectly adding $180$ to the interior angle instead of subtracting from $180$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MF7YCI', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line in the $xy$-plane has the equation $\\frac{x}{11} + \\frac{y}{-4} = 1$. What is the slope of a line perpendicular to this line?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{11}{4}$"},{"key":"B","text":"$-\\frac{4}{11}$"},{"key":"C","text":"$\\frac{4}{11}$"},{"key":"D","text":"$\\frac{11}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $-\\frac{11}{4}$. Rewrite the equation $\\frac{x}{11} + \\frac{y}{-4} = 1$ as $\\frac{x}{11} - \\frac{y}{4} = 1$. Multiplying both sides by $44$ gives $4x - 11y = 44$, so $y = \\frac{4}{11}x - 4$ and the slope of the original line is $\\frac{4}{11}$. A perpendicular line has slope equal to the negative reciprocal, which is $-\\frac{11}{4}$. The result $\\frac{4}{11}$ is the slope of the original line itself, not its perpendicular. The result $-\\frac{4}{11}$ comes from negating the slope without taking the reciprocal, confusing perpendicularity with mere sign reversal. The result $\\frac{11}{4}$ comes from taking the reciprocal without negating, which is the slope condition for neither parallel nor perpendicular lines.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MFCE75', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $\\frac{4x^2 - 25}{2x^2 + 9x + 10}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2x + 5}{x + 2}$"},{"key":"B","text":"$\\frac{2x - 5}{x + 2}$"},{"key":"C","text":"$\\frac{2x - 5}{x + 5}$"},{"key":"D","text":"$2 - \\frac{5}{x + 2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $\\frac{2x - 5}{x + 2}$. The numerator $4x^2 - 25$ is a difference of squares: $(2x - 5)(2x + 5)$. The denominator $2x^2 + 9x + 10$ factors as $(2x + 5)(x + 2)$, since $2x \\cdot x = 2x^2$, $2x \\cdot 2 + 5 \\cdot x = 4x + 5x = 9x$, and $5 \\cdot 2 = 10$. Cancelling the common factor $(2x + 5)$ yields $\\frac{2x - 5}{x + 2}$. The expression $\\frac{2x + 5}{x + 2}$ results from cancelling $(2x - 5)$ instead of $(2x + 5)$, a sign error in identifying which factor is shared. The expression $\\frac{2x - 5}{x + 5}$ comes from incorrectly factoring the denominator as $(2x + 5)(x + 5)$ instead of $(2x + 5)(x + 2)$. The expression $2 - \\frac{5}{x + 2}$ attempts partial-fraction decomposition but arrives at a wrong remainder; the actual decomposition of $\\frac{2x - 5}{x + 2}$ is $2 - \\frac{9}{x + 2}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N1NKQB', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $\\frac{x - 13}{4} = 7$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$24$"},{"key":"C","text":"$28$"},{"key":"D","text":"$41$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $41$. Multiply both sides of the equation by $4$ to get $x - 13 = 28$, then add $13$ to both sides to get $x = 41$. The result $28$ comes from stopping after the first step and not adding $13$ back. The result $15$ comes from subtracting $13$ from $28$ instead of adding, a sign error. The result $24$ comes from incorrectly adding $4 + 7 + 13$ rather than multiplying $4 \\times 7$ and then adding $13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N1UWAN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2(x + 3)^2 + 18$. What is the maximum value of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$3$"},{"key":"C","text":"$8$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $18$. The function is in vertex form $h(x) = -2(x + 3)^2 + 18$. Because the leading coefficient $-2$ is negative, the parabola opens downward and the vertex represents the maximum. The vertex is at $(-3, 18)$, so the maximum value is $18$. The value $-3$ is the $x$-coordinate of the vertex, not the maximum output. The value $3$ confuses the sign of the vertex $x$-coordinate. The value $8$ comes from an arithmetic error in identifying the vertex value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NBY1UI', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'For what value of $c$ does the equation $3(cx - 2) + 9 = 21x - 11$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $7$. Distributing on the left side gives $3cx - 6 + 9 = 21x - 11$, which simplifies to $3cx + 3 = 21x - 11$. For the equation to have no solution, the coefficients of $x$ must be equal while the constant terms differ. Setting $3c = 21$ gives $c = 7$. With $c = 7$, the equation becomes $21x + 3 = 21x - 11$, which simplifies to $3 = -11$, a contradiction confirming no solution exists. The value $3$ comes from dividing $3$ (the constant on the left) by $1$ or other partial reasoning without correctly identifying the no-solution condition. The value $-7$ is a sign error when solving $3c = 21$. The value $21$ confuses the coefficient of $x$ on the right side with the value of $c$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OJ2BZY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $x^2 + y^2 = 89$ and $x - y = 3$, what is the value of $xy$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40', ARRAY['40'], E'The correct answer is $40$. Rather than solving for $x$ and $y$ individually, use the algebraic identity $(x - y)^2 = x^2 - 2xy + y^2$. Since $x - y = 3$, we have $(x - y)^2 = 9$, which means $x^2 - 2xy + y^2 = 9$. Substituting $x^2 + y^2 = 89$ gives $89 - 2xy = 9$, so $2xy = 80$ and $xy = 40$. A common error is to compute $(x - y)^2 = x^2 + y^2 - 2xy$ correctly but then set $89 + 2xy = 9$ by mishandling the sign, yielding $xy = -40$. Another error is solving for $x$ and $y$ but using only one solution pair and misreading the product.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P3BFD8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g(x) = 2x^3 - 11$. What is the value of $g(-1)$?', NULL, $lyceon_json$[{"key":"A","text":"$-13$"},{"key":"B","text":"$-9$"},{"key":"C","text":"$9$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $-13$. Substituting $x = -1$ gives $g(-1) = 2(-1)^3 - 11 = 2(-1) - 11 = -2 - 11 = -13$. The value $-9$ results from computing $2(1) - 11 = -9$, treating $(-1)^3$ as $1$ instead of $-1$. The value $9$ comes from computing $-2 - 11$ with incorrect signs. The value $13$ results from dropping the negative sign entirely and computing $2 + 11$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PY3E7G', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the following system of equations have no solution? $$7x - 4y = 15$$ $$21x + ky = 10$$', NULL, $lyceon_json$[{"key":"A","text":"$-12$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$4$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $-12$. A system of linear equations has no solution when the lines are parallel, meaning the ratios of corresponding coefficients are equal but the ratio of constants differs. Setting $\\frac{7}{21} = \\frac{-4}{k}$ gives $\\frac{1}{3} = \\frac{-4}{k}$, so $k = -12$. Checking the constant ratio: $\\frac{15}{10} = \\frac{3}{2} \\neq \\frac{1}{3}$, confirming no solution exists. The value $12$ results from dropping the negative sign when solving for $k$. The value $-3$ comes from dividing the $x$-coefficients ($21 \\div 7 = 3$) and applying a negative sign without properly setting up the proportion involving the $y$-coefficients. The value $4$ results from incorrectly concluding that $k$ must equal the absolute value of the $y$-coefficient in the first equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QQ6WWG', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ in the solution to the following system of equations? $$2x + y = 17$$ $$x - y = 4$$', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $7$. Adding the two equations eliminates $y$: $(2x + y) + (x - y) = 17 + 4$, giving $3x = 21$ and $x = 7$. The value $3$ is the $y$-value of the solution, not the $x$-value, found by substituting $x = 7$ back into $x - y = 4$ to get $y = 3$. The value $5$ results from an arithmetic error when combining the equations. The value $10$ comes from incorrectly setting up the elimination step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QYVEAZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'A right triangle has a hypotenuse of length $29$ and one leg of length $20$. What is the length of the other leg?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'The correct answer is $21$. Using the Pythagorean theorem, if the hypotenuse is $29$ and one leg is $20$, then the other leg satisfies $20^2 + b^2 = 29^2$. Computing, $400 + b^2 = 841$, so $b^2 = 441$, and $b = \\sqrt{441} = 21$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S2310K', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'If $3x^2 = 147$, what is the positive value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$21$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $7$. Dividing both sides by $3$ gives $x^2 = 49$, and taking the positive square root yields $x = 7$. The value $3$ comes from extracting the coefficient instead of solving. The value $21$ results from dividing $147$ by $3$ but forgetting to take the square root. The value $49$ is the result of $x^2$ itself, not $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SIY36C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a data set is given by $y = 1.73x + 12.4$, where $x$ represents the number of hours studied and $y$ represents the test score. One data point in the set is $(9, 29.1)$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$1.13$"},{"key":"B","text":"$-1.13$"},{"key":"C","text":"$27.97$"},{"key":"D","text":"$0.87$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $1.13$. The predicted value is $y = 1.73(9) + 12.4 = 15.57 + 12.4 = 27.97$. The residual equals the actual value minus the predicted value: $29.1 - 27.97 = 1.13$. The result $-1.13$ reverses the subtraction order, computing predicted minus actual. The result $27.97$ is the predicted value itself, not the residual. The result $0.87$ comes from an arithmetic error in the subtraction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TS1UOT', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{3(2x - 7)}{4} = 9$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{2}$"},{"key":"B","text":"$\\frac{29}{6}$"},{"key":"C","text":"$\\frac{15}{2}$"},{"key":"D","text":"$\\frac{43}{6}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{19}{2}$. Multiply both sides by $4$ to get $3(2x - 7) = 36$. Distribute the $3$ to obtain $6x - 21 = 36$. Add $21$ to both sides: $6x = 57$. Divide by $6$: $x = \\frac{57}{6} = \\frac{19}{2}$. The value $\\frac{29}{6}$ results from dividing $9$ by $3$ first to get $3$ and then solving $2x - 7 = 3$ incorrectly. The value $\\frac{15}{2}$ comes from not multiplying $9$ by $4$, effectively solving $3(2x - 7) = 9$ directly, which gives $6x - 21 = 9$ and $x = 5$; the fraction form suggests a different arithmetic path yielding a nearby wrong value. The value $\\frac{43}{6}$ results from an arithmetic slip when adding $21$ to $36$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TW2BYH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'Let $f(x) = 3x - 7$ and $g(x) = x^2 - 5x + 2$. If $g(f(t)) = -2$, what is the greater of the two possible values of $t$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/3', ARRAY['11/3', '3.666', '3.667'], E'The correct answer is $\\frac{11}{3}$. First compute the composition $g(f(t))$ by substituting $f(t) = 3t - 7$ into $g$: $g(3t - 7) = (3t - 7)^2 - 5(3t - 7) + 2 = 9t^2 - 42t + 49 - 15t + 35 + 2 = 9t^2 - 57t + 86$. Setting $9t^2 - 57t + 86 = -2$ gives $9t^2 - 57t + 88 = 0$. The discriminant is $57^2 - 4(9)(88) = 3249 - 3168 = 81$, so $t = \\frac{57 \\pm 9}{18}$, yielding $t = \\frac{66}{18} = \\frac{11}{3}$ or $t = \\frac{48}{18} = \\frac{8}{3}$. The greater value is $\\frac{11}{3}$. A common error is expanding $(3t - 7)^2$ incorrectly as $9t^2 - 21t + 49$, which changes the linear coefficient and produces wrong roots. Another error is finding both values but reporting $\\frac{8}{3}$ by confusing which is larger.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UWXJVQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A town''s population was $53{,}000$ in 2021. By 2023, the population had grown to $58{,}433$. If the population increased by the same percent each year, what is the approximate annual percent increase?', NULL, $lyceon_json$[{"key":"A","text":"$4.7\\%$"},{"key":"B","text":"$5.0\\%$"},{"key":"C","text":"$5.5\\%$"},{"key":"D","text":"$10.3\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $5.0\\%$. The total growth factor over $2$ years is $\\frac{58{,}433}{53{,}000} \\approx 1.1025$. Because the population grew by the same percent each year, the annual growth factor is $\\sqrt{1.1025} = 1.05$, corresponding to a $5.0\\%$ annual increase. Verification: $53{,}000 \\times 1.05 = 55{,}650$ and $55{,}650 \\times 1.05 = 58{,}432.50 \\approx 58{,}433$. The answer $4.7\\%$ underestimates the rate from a computation error. The answer $5.5\\%$ overestimates the rate, possibly from an incorrect setup. The answer $10.3\\%$ treats the total two-year percent change ($\\frac{5{,}433}{53{,}000} \\approx 10.25\\%$) as the annual rate instead of taking the square root for compounding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V021Y0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A sector of a circle has an area of $\\frac{169\\pi}{6}$ square centimeters and a radius of $13$ centimeters. What is the arc length, in centimeters, of the sector?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13\\pi}{3}$"},{"key":"B","text":"$\\frac{13\\pi}{6}$"},{"key":"C","text":"$\\frac{26\\pi}{3}$"},{"key":"D","text":"$\\frac{169\\pi}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{13\\pi}{3}$. First, find the central angle using the sector area formula $A = \\frac{1}{2}r^2\\theta$: $\\frac{169\\pi}{6} = \\frac{1}{2}(169)\\theta$, which gives $\\theta = \\frac{\\pi}{3}$ radians. Then the arc length is $s = r\\theta = 13 \\cdot \\frac{\\pi}{3} = \\frac{13\\pi}{3}$. The value $\\frac{13\\pi}{6}$ results from using $\\frac{\\theta}{2}$ instead of $\\theta$ in the arc length formula, failing to properly isolate the angle. The value $\\frac{26\\pi}{3}$ uses the diameter instead of the radius when computing arc length. The value $\\frac{169\\pi}{3}$ uses $r^2$ instead of $r$ in the arc length formula, confusing $s = r\\theta$ with $s = r^2\\theta$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V5CYWD', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'The equation $3x + 5y = 45$ represents a relationship between $x$ and $y$. What is the value of $y$ when $x = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$15$"},{"key":"C","text":"$45$"},{"key":"D","text":"$-9$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $9$. Substituting $x = 0$ into $3(0) + 5y = 45$ gives $5y = 45$. Dividing both sides by $5$ yields $y = 9$. The value $15$ comes from dividing $45$ by $3$ instead of $5$, confusing the coefficients. The value $45$ results from ignoring the coefficient of $y$ entirely. The value $-9$ is a sign error applied when dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VFWNBR', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(3x + 11)(2x - 5)$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^2 + 7x - 55$"},{"key":"B","text":"$6x^2 - 7x - 55$"},{"key":"C","text":"$6x^2 + 7x + 55$"},{"key":"D","text":"$6x^2 + 37x - 55$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $6x^2 + 7x - 55$. Using the distributive property: $(3x)(2x) = 6x^2$, $(3x)(-5) = -15x$, $(11)(2x) = 22x$, and $(11)(-5) = -55$. Combining the middle terms gives $-15x + 22x = 7x$, so the result is $6x^2 + 7x - 55$. The expression $6x^2 - 7x - 55$ reverses the sign of the middle term, computing $15x - 22x$ instead of $-15x + 22x$. The expression $6x^2 + 7x + 55$ incorrectly makes the constant term positive. The expression $6x^2 + 37x - 55$ adds the magnitudes of the middle terms ($15 + 22 = 37$) instead of combining $-15 + 22$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VGV699', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of $400$ residents from a city of $52{,}000$ found that $68\\%$ of respondents support a new park proposal. The margin of error for the survey is $\\pm 4.6\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $63.4\\%$ and $72.6\\%$ of all city residents are likely to support the proposal."},{"key":"B","text":"Exactly $68\\%$ of all city residents support the proposal."},{"key":"C","text":"Between $63.4\\%$ and $72.6\\%$ of the $400$ surveyed residents support the proposal."},{"key":"D","text":"The survey is unreliable because the sample size is less than $1\\%$ of the population."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that between $63.4\\%$ and $72.6\\%$ of all city residents are likely to support the proposal. The margin of error creates a confidence interval: $68\\% \\pm 4.6\\%$ yields the range $63.4\\%$ to $72.6\\%$, which estimates the true population proportion. The claim that exactly $68\\%$ of all residents support the proposal treats the sample statistic as the exact population parameter, ignoring sampling variability. The claim about the $400$ surveyed residents misapplies the confidence interval to the sample rather than the population. The claim that the survey is unreliable because of sample size is incorrect; statistical reliability depends on absolute sample size and methodology, not on the ratio of sample to population.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VQSPR5', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $p$ has the equation $7x - 2y = 26$. What is the $y$-coordinate of the point on line $p$ where $x = 6$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Substitute $x = 6$ into $7x - 2y = 26$: $7(6) - 2y = 26$, which gives $42 - 2y = 26$. Subtract $42$ from both sides: $-2y = -16$. Divide by $-2$: $y = 8$. A common error is forgetting the negative sign when dividing, which would yield $y = -8$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WINHMY', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A small business owner sells handmade candles for \\$14 each. The cost to produce $c$ candles is $(6c + 190)$ dollars. What is the minimum number of candles the owner must sell to earn a profit of more than \\$250?', NULL, $lyceon_json$[{"key":"A","text":"$24$"},{"key":"B","text":"$32$"},{"key":"C","text":"$55$"},{"key":"D","text":"$56$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $56$. Profit equals revenue minus cost: $14c - (6c + 190) = 8c - 190$. Setting up the inequality $8c - 190 > 250$ gives $8c > 440$, so $c > 55$. Since $c$ must be a whole number, the minimum is $56$. The value $55$ results from not recognizing that the inequality is strict, so profit at $55$ candles equals exactly \\$250, which does not exceed \\$250. The value $32$ comes from ignoring the fixed cost of \\$190 and solving $8c > 250$. The value $24$ comes from finding only the break-even point where profit exceeds \\$0 rather than \\$250.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WKT236', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'Lines $p$ and $q$ are parallel and are cut by transversal $t$. One of the angles formed where $t$ intersects line $p$ measures $(3x + 14)^\\circ$. The alternate interior angle formed where $t$ intersects line $q$ measures $(5x - 22)^\\circ$. What is the measure, in degrees, of the supplement of the angle $(3x + 14)^\\circ$?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$68$"},{"key":"C","text":"$102$"},{"key":"D","text":"$112$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $112$. Since lines $p$ and $q$ are parallel, alternate interior angles are equal: $3x + 14 = 5x - 22$. Solving gives $36 = 2x$, so $x = 18$. The angle $(3x + 14)^\\circ = 3(18) + 14 = 68^\\circ$. Its supplement is $180 - 68 = 112$ degrees. The value $18$ is only the value of $x$, not the requested angle measure. The value $68$ is the angle itself rather than its supplement. The value $102$ results from an arithmetic error when computing $180 - 68$.', $lyceon_json${"D":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X8K31Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylinder has a radius of $3$ and a height of $\\frac{14}{\\pi}$. What is the volume of the cylinder?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '126', ARRAY['126'], E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting $r = 3$ and $h = \\frac{14}{\\pi}$ gives $V = \\pi (3)^2 \\cdot \\frac{14}{\\pi} = \\pi \\cdot 9 \\cdot \\frac{14}{\\pi} = 9 \\cdot 14 = 126$. The factor of $\\pi$ in the formula cancels with the $\\pi$ in the denominator of the height.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XHYQWE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $29^\\circ$ and the measure of angle $Q$ is $67^\\circ$. What is the measure of the exterior angle at vertex $R$?', NULL, $lyceon_json$[{"key":"A","text":"$84^\\circ$"},{"key":"B","text":"$96^\\circ$"},{"key":"C","text":"$113^\\circ$"},{"key":"D","text":"$151^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $96^\\circ$. By the exterior angle theorem, the measure of an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. The exterior angle at vertex $R$ is therefore $29^\\circ + 67^\\circ = 96^\\circ$. The answer $84^\\circ$ is the interior angle at $R$ (found by $180^\\circ - 29^\\circ - 67^\\circ$), which is the wrong angle requested. The answer $113^\\circ$ results from incorrectly adding the interior angle at $R$ to one remote interior angle ($84^\\circ + 29^\\circ$). The answer $151^\\circ$ comes from adding the adjacent interior angle to one remote angle ($84^\\circ + 67^\\circ$), confusing which angles the theorem uses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XO2G0J', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $p(x) = x^2 - 8x + k$ has a minimum value of $-3$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'Completing the square gives $p(x) = (x - 4)^2 - 16 + k$. The minimum value of $(x - 4)^2$ is $0$, occurring at $x = 4$, so the minimum value of $p(x)$ is $k - 16$. Setting $k - 16 = -3$ gives $k = 13$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YA7YI4', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $m$ passes through $(1, -3)$ and is perpendicular to the line $5x - 3y = 18$. What is the $y$-intercept of line $m$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{12}{5}$"},{"key":"B","text":"$-\\frac{18}{5}$"},{"key":"C","text":"$\\frac{12}{5}$"},{"key":"D","text":"$-\\frac{3}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $-\\frac{12}{5}$. Rewrite $5x - 3y = 18$ in slope-intercept form: $y = \\frac{5}{3}x - 6$, so the slope is $\\frac{5}{3}$. A line perpendicular to this has slope $-\\frac{3}{5}$. Using the point $(1, -3)$: $-3 = -\\frac{3}{5}(1) + b$, so $b = -3 + \\frac{3}{5} = -\\frac{15}{5} + \\frac{3}{5} = -\\frac{12}{5}$. The value $-\\frac{18}{5}$ results from an arithmetic slip, such as computing $-\\frac{15}{5} - \\frac{3}{5}$ instead of adding. The value $\\frac{12}{5}$ comes from dropping the negative sign on the result. The value $-\\frac{3}{5}$ confuses the perpendicular slope with the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YCFINZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If the equation $x^2 - 14x + k = 0$ has exactly one real solution, what is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$14$"},{"key":"C","text":"$49$"},{"key":"D","text":"$196$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $49$. A quadratic equation has exactly one real solution when its discriminant equals zero. Setting $b^2 - 4ac = 0$ gives $(-14)^2 - 4(1)(k) = 0$, so $196 - 4k = 0$ and $k = 49$. The value $7$ is half of $14$, not the discriminant condition. The value $14$ simply repeats the coefficient of $x$. The value $196$ is $(-14)^2$ without completing the discriminant calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z806CM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f(x) = (x - 4)^2 - 5$. What is the value of $f(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$4$"},{"key":"C","text":"$14$"},{"key":"D","text":"$44$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $4$. Substituting $x = 7$ gives $f(7) = (7 - 4)^2 - 5 = 3^2 - 5 = 9 - 5 = 4$. The value $-5$ results from ignoring the squared term and returning only the constant. The value $14$ comes from adding $9 + 5$ instead of subtracting. The value $44$ comes from computing $7^2 - 5 = 49 - 5$ without applying the shift.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZGZ61C', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has center $(-7, 4)$ and radius $\\sqrt{11}$. Which of the following is the equation of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 7)^2 + (y - 4)^2 = 11$"},{"key":"B","text":"$(x - 7)^2 + (y + 4)^2 = 11$"},{"key":"C","text":"$(x + 7)^2 + (y - 4)^2 = \\sqrt{11}$"},{"key":"D","text":"$(x + 7)^2 + (y - 4)^2 = 121$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $(x + 7)^2 + (y - 4)^2 = 11$. The standard form of a circle with center $(h, k)$ and radius $r$ is $(x - h)^2 + (y - k)^2 = r^2$. Substituting $h = -7$, $k = 4$, and $r = \\sqrt{11}$ gives $(x + 7)^2 + (y - 4)^2 = 11$. The equation $(x - 7)^2 + (y + 4)^2 = 11$ reverses the signs on both center coordinates. The equation with $\\sqrt{11}$ on the right side fails to square the radius. The equation with $121$ on the right side incorrectly computes $r^2$ as $11^2 = 121$ instead of $(\\sqrt{11})^2 = 11$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21QND0N', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The Kepler space telescope, launched in 2009, was designed to detect planets orbiting distant stars by measuring tiny dips in starlight. Over its nine-year mission, it identified more than 2,600 confirmed exoplanets. _Many of these planets orbit within the habitable zones of their host stars, where liquid water could theoretically exist on the surface._', $lyceon_json$[{"key":"A","text":"It provides a specific detail that elaborates on Kepler's discoveries."},{"key":"B","text":"It challenges a claim made earlier in the passage about Kepler's mission."},{"key":"C","text":"It introduces a new topic unrelated to the rest of the passage."},{"key":"D","text":"It summarizes the passage's main argument about space exploration."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the sentence provides a specific detail elaborating on Kepler''s discoveries. The underlined sentence adds information about the nature of the discovered planets — specifically their location in habitable zones — building on the preceding statement about the total number of confirmed exoplanets. The choice suggesting the sentence challenges an earlier claim is incorrect because no contradiction or counterargument is present; the sentence extends the discussion. The choice claiming a new unrelated topic is introduced is wrong because habitable-zone planets are directly connected to Kepler''s exoplanet discoveries. The choice describing a summary of a main argument is inaccurate because the sentence adds a narrower detail rather than restating the passage''s overall point.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21T91LC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The archive''s newly digitized collection of nineteenth-century daguerreotypes, along with a set of handwritten letters donated by the Whitford estate, _______ researchers an unprecedented opportunity to trace the social networks of free Black communities in antebellum Philadelphia.', $lyceon_json$[{"key":"A","text":"offer"},{"key":"B","text":"offers"},{"key":"C","text":"are offering"},{"key":"D","text":"have offered"}]$lyceon_json$::jsonb, 'B', NULL, E'The true subject of the sentence is "collection," which is singular. The phrase "along with a set of handwritten letters donated by the Whitford estate" is a parenthetical addition set off by commas; it does not form a compound subject. Therefore, the verb must be singular: "offers." The choice "offer" is a plural verb form that incorrectly treats the subject as plural, likely because the intervening phrase mentions additional items. The choice "are offering" uses a plural auxiliary verb, committing the same agreement error while also shifting to the progressive aspect without contextual justification. The choice "have offered" uses a plural auxiliary and shifts to the present perfect tense, but the passage describes the current state of a newly digitized collection, making the simple present the appropriate tense.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24Z9XMX', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a music historian would most effectively illustrate the claim that Zitkala-Sa used her compositions to challenge prevailing stereotypes?', E'Zitkala-Sa, a Yankton Dakota writer and activist born in 1876, co-composed The Sun Dance Opera in 1913, blending traditional Lakota melodies with Western operatic forms. Some scholars argue that this work was a deliberate artistic response to the widespread portrayal of Indigenous music as primitive. By integrating Indigenous themes into a genre associated with European high culture, Zitkala-Sa sought to demonstrate the sophistication and emotional depth of Native musical traditions to audiences who might otherwise dismiss them.', $lyceon_json$[{"key":"A","text":"\"Zitkala-Sa's literary essays from the early 1900s remain among the most widely anthologized works of Native American autobiography.\""},{"key":"B","text":"\"In The Sun Dance Opera, Zitkala-Sa placed Lakota ceremonial motifs within sonata structures, forcing audiences to confront the complexity they had been taught to deny in Indigenous art.\""},{"key":"C","text":"\"The Sun Dance Opera premiered at a time when most American opera companies were performing exclusively Italian and German repertoire.\""},{"key":"D","text":"\"Zitkala-Sa spent several years studying violin at the New England Conservatory before turning to writing and political activism.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the quotation stating that Zitkala-Sa placed Lakota ceremonial motifs within sonata structures, forcing audiences to confront the complexity they had been taught to deny in Indigenous art. This directly illustrates how her composition challenged stereotypes by embedding Indigenous music into Western forms to reveal its sophistication. The quotation about her literary essays concerns her writing career, not her musical compositions'' role in challenging stereotypes. The quotation about opera companies performing Italian and German repertoire provides historical context about the opera landscape but does not address how Zitkala-Sa''s work challenged perceptions of Indigenous music. The quotation about her violin studies at the New England Conservatory describes her musical training rather than demonstrating how her compositions confronted prevailing stereotypes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26VOD0R', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely respond to the argument presented in Text 2?', E'Text 1: Historian Priya Menon argues that the construction of large-scale irrigation systems in ancient Mesopotamia was coordinated by centralized state authorities. She cites the uniformity of canal dimensions across the Tigris-Euphrates floodplain and the administrative tablets recovered from Ur that record labor conscription specifically for waterway maintenance. According to Menon, only a bureaucratic apparatus with coercive power could have mobilized the thousands of laborers these projects required.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2876WV1', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing a research summary for a science journal, a student wants to introduce the significance of a recent finding to readers who may be unfamiliar with deep-ocean bioluminescence. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DCF5I8', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the novelist Tomoko Ishida initially envisioned her 2021 work, The Clockmaker''s Apprentice, as a straightforward historical _______ early drafts convinced her editor, Marcus Bellingham, that the manuscript''s strongest passages were those blending speculative fiction with meticulously researched accounts of seventeenth-century Nuremberg.', $lyceon_json$[{"key":"A","text":"fiction, the"},{"key":"B","text":"fiction; the"},{"key":"C","text":"fiction. The"},{"key":"D","text":"fiction the"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence begins with the subordinating conjunction "Although," which introduces a dependent clause. This dependent clause must be joined to the main clause ("early drafts convinced her editor...") with a comma, making the choice with a comma and lowercase "the" the correct option. The choice using a semicolon incorrectly treats the dependent clause as an independent clause, since a semicolon can only join two independent clauses. The choice using a period similarly fragments the sentence by severing the dependent clause from its main clause. The choice omitting all punctuation creates a boundary error by running the dependent clause directly into the main clause without the required comma after an introductory subordinate clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E1U9ET', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The veiled chameleon (Chamaeleo calyptratus) is native to the humid plateaus and mountain slopes of Yemen and Saudi Arabia. Unlike many reptile species that rely solely on insects for nutrition, the veiled chameleon regularly consumes plant matter, including leaves and fruit. Herpetologists believe this dietary flexibility evolved because ________', $lyceon_json$[{"key":"A","text":"chameleons in captivity prefer commercially prepared diets over live insects."},{"key":"B","text":"the veiled chameleon's distinctive casque is larger than that of most other chameleon species."},{"key":"C","text":"the arid periods common in the chameleon's native habitat can drastically reduce insect availability, making plant consumption a critical supplementary food source."},{"key":"D","text":"most reptile species in the Arabian Peninsula are strictly nocturnal hunters."}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is that arid periods in the chameleon''s native habitat can drastically reduce insect availability, making plant consumption a critical supplementary food source. This logically completes the text by providing an environmental explanation for the dietary flexibility described in the passage. The claim about captive chameleons preferring commercial diets addresses captive conditions, not the evolutionary pressures in the wild that the passage is discussing. The observation about the veiled chameleon''s casque size concerns a physical feature unrelated to diet. The assertion that most Arabian Peninsula reptiles are strictly nocturnal hunters introduces information about other species'' behavior that does not explain why the veiled chameleon specifically evolved to eat plants.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E61MVM', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the restoration team finished removing centuries of varnish from the seventeenth-century altarpiece, they _______ that the original pigments underneath were far more vivid than any reproduction had suggested.', $lyceon_json$[{"key":"A","text":"will discover"},{"key":"B","text":"have discovered"},{"key":"C","text":"had discovered"},{"key":"D","text":"would have been discovering"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence describes a sequence of past events: the restoration team finished removing varnish, and by that point they had already made a discovery. The past perfect tense "had discovered" correctly indicates an action completed before another past action ("finished"). The choice "will discover" incorrectly shifts to the future tense in a sentence that is entirely about past events. The choice "have discovered" uses the present perfect, which connects past actions to the present, but this sentence is set entirely in the past. The choice "would have been discovering" uses the past conditional progressive, implying a hypothetical ongoing action, which does not fit the context of a completed discovery.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FJ61CT', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The architect Lina Bo Bardi is celebrated for her bold use of raw concrete and exposed structural elements in buildings like the S\\u00e3o Paulo Museum of Art. Her approach to materials was not purely aesthetic, however; she believed that leaving surfaces unfinished communicated honesty about the construction process. _______ Bo Bardi frequently incorporated salvaged wood, river stones, and other locally sourced elements into her designs, viewing the imperfections in these materials as vital expressions of regional identity.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"Consistent with this philosophy,"},{"key":"D","text":"On the other hand, surprisingly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "Consistent with this philosophy," because the preceding sentence establishes Bo Bardi''s belief that unfinished surfaces communicate honesty, and the final sentence provides an additional practice (incorporating salvaged materials) that aligns with and extends that same belief. "Nevertheless" incorrectly signals a contrast, but the final sentence reinforces rather than contradicts the preceding idea. "Specifically" would indicate a narrowing or exemplification of the same point, but incorporating salvaged wood and stones is a separate but aligned practice, not a specific instance of leaving concrete unfinished. "On the other hand" incorrectly introduces an opposing perspective when the final sentence actually supports the stated philosophy.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ICY7ZZ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'In a 2023 study, geochemist Priya Nandakumar analyzed strontium isotope ratios in fossilized teeth from early Pleistocene herbivores discovered in central Kenya. Her data suggested that these animals migrated seasonally across distances exceeding 400 kilometers, a pattern previously undocumented for species in the region. _______ an independent team examining the same fossil assemblage found that carbon isotope signatures in the tooth enamel pointed to a diet of lowland grasses, which would have been available only along the animals'' proposed migratory corridor.', $lyceon_json$[{"key":"A","text":"In contrast,"},{"key":"B","text":"Reinforcing this conclusion,"},{"key":"C","text":"Granted,"},{"key":"D","text":"For this particular reason,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "Reinforcing this conclusion," because the independent team''s finding about carbon isotope signatures provides additional, converging evidence for Nandakumar''s migration hypothesis. "In contrast" incorrectly signals disagreement between the two teams, but both sets of findings point in the same direction. "Granted" is used to concede a point before introducing a counterargument, yet the second finding does not function as a concession or qualification. "For this reason" implies that the independent team''s work was caused by Nandakumar''s conclusion, but the passage presents the second study as separate corroborating evidence, not as a consequence of the first study''s findings.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ILNGP0', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason historians have revised their understanding of the Nabataean water system?', E'For decades, historians attributed the prosperity of Petra, the ancient Nabataean capital carved into sandstone cliffs in modern-day Jordan, primarily to its position along lucrative trade routes. However, recent archaeological surveys of the surrounding desert have revealed an elaborate network of cisterns, channels, and dams that captured and redirected seasonal floodwaters. These hydraulic structures, some capable of storing over 37,000 liters, enabled year-round habitation in a region receiving fewer than 130 millimeters of annual rainfall. Scholars now argue that the Nabataeans'' mastery of water engineering, rather than trade alone, was the indispensable foundation of Petra''s sustained growth.', $lyceon_json$[{"key":"A","text":"Trade routes through Petra were less profitable than historians had originally estimated."},{"key":"B","text":"The cisterns discovered near Petra were built by a civilization that predated the Nabataeans."},{"key":"C","text":"Archaeological evidence has shown that the Nabataeans' water infrastructure was essential to sustaining Petra's development, not merely its trade position."},{"key":"D","text":"Petra's sandstone cliffs naturally retained enough moisture to support a small population without engineered systems."}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is that archaeological evidence has shown the Nabataeans'' water infrastructure was essential to sustaining Petra''s development, not merely its trade position. The passage explicitly states that scholars now argue water engineering, rather than trade alone, was the indispensable foundation of Petra''s growth. The claim that trade routes were less profitable than originally estimated goes beyond the text, which revises the relative importance of trade versus water management but never questions trade profitability. The suggestion that the cisterns predate the Nabataeans contradicts the passage, which attributes them to Nabataean construction. The idea that sandstone cliffs naturally retained moisture conflicts with the passage''s emphasis on engineered systems in a region receiving under 130 millimeters of rain annually.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JGY4N3', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists studying the migration patterns of leatherback sea turtles have long relied on satellite tags to track individual animals across ocean basins. These tags, however, can detach prematurely during deep dives, leaving gaps in the data. _______ researchers at the Coastal Marine Institute recently developed a more durable tag that withstands pressures at depths exceeding 1,200 meters.', $lyceon_json$[{"key":"A","text":"To address this problem,"},{"key":"B","text":"In other words, then,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"As a result,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "To address this problem," because the preceding sentences describe a specific challenge (tags detaching prematurely during deep dives), and the final sentence introduces a solution developed by researchers. "In other words" incorrectly signals a restatement rather than a problem-solution relationship. "Similarly" incorrectly signals a comparison, but the final sentence offers a remedy, not a parallel scenario. "As a result" incorrectly implies that the new tag is a consequence of the problem rather than a deliberate response to it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K5HT2K', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if accurate, would most directly undermine the researchers'' conclusion?', E'A team of marine biologists studying coral bleaching events in the Coral Triangle published a report in 2023 arguing that a specific strain of the symbiotic alga Symbiodinium thermophilum confers meaningful heat resistance to its coral hosts. The researchers based this conclusion on laboratory trials in which coral fragments colonized by S. thermophilum withstood water temperatures of 33 degrees Celsius for 19 days without bleaching, while control fragments colonized by the more common strain S. microadriaticum bleached within 7 days. The team proposed that encouraging the natural spread of S. thermophilum could serve as a viable strategy for protecting reefs threatened by warming oceans.', $lyceon_json$[{"key":"A","text":"S. thermophilum is found in higher concentrations in the western Pacific than in the eastern Pacific."},{"key":"B","text":"Laboratory trials conducted at 31 degrees Celsius showed that both algal strains performed equally well over 19 days."},{"key":"C","text":"Other symbiotic algae besides S. thermophilum have also been shown to provide some heat resistance to certain coral species."},{"key":"D","text":"In open-ocean field trials, corals colonized by S. thermophilum bleached at the same rate as corals colonized by S. microadriaticum when exposed to comparable temperature increases over similar durations."}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is that in open-ocean field trials, corals with S. thermophilum bleached at the same rate as those with S. microadriaticum under comparable conditions. This directly undermines the researchers'' conclusion by showing that the laboratory-observed heat resistance does not replicate in natural settings, which is critical for their proposal to protect reefs through S. thermophilum spread. The geographic distribution of S. thermophilum in the western versus eastern Pacific is irrelevant to whether it actually confers heat resistance. The finding that both strains performed equally at 31 degrees is only partially relevant because the researchers'' key trials were conducted at 33 degrees; equal performance at a lower temperature does not contradict the finding at the higher, more stressful temperature. The existence of other algae that also provide heat resistance does not undermine the specific claim about S. thermophilum; it merely broadens the picture without contradicting the conclusion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KQS6TN', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2019 survey of urban beekeepers across eleven midwestern cities, entomologist Priya Ramanathan found that colonies housed on rooftops with partial shade produced 37 percent more honey than those in direct _______ Ramanathan attributed the difference to reduced thermal stress on foraging workers during peak afternoon hours.', $lyceon_json$[{"key":"A","text":"sunlight,"},{"key":"B","text":"sunlight;"},{"key":"C","text":"sunlight"},{"key":"D","text":"sunlight, however,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses a semicolon to join two closely related independent clauses without a coordinating conjunction. The choice using only a comma creates a comma splice, which is a sentence boundary error: a comma alone cannot join two independent clauses without a coordinating conjunction. The choice using no punctuation at all creates a run-on sentence by fusing two independent clauses with nothing between them. The choice using "however" with commas misrepresents the logical relationship: the second clause explains the finding rather than contrasting with it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KXYE6O', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the ecologist''s hypothesis?', E'An ecologist studying salt marshes along the coast of Georgia hypothesized that the invasive grass Phragmites australis reduces habitat quality for the diamondback terrapin by forming dense stands that block the terrapins'' access to open nesting areas. If this hypothesis is correct, sites with higher Phragmites density should show measurable effects on terrapin nesting success.', $lyceon_json$[{"key":"A","text":"Terrapins nesting in areas with dense Phragmites cover produce significantly fewer viable hatchlings than terrapins nesting in areas where Phragmites is absent."},{"key":"B","text":"Phragmites australis grows more rapidly in marshes with higher salinity levels than in those with lower salinity."},{"key":"C","text":"Diamondback terrapins in Georgia have a longer nesting season than terrapins in mid-Atlantic states."},{"key":"D","text":"Several other invasive plant species have also been observed spreading through Georgia's coastal wetlands."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that terrapins nesting in areas with dense Phragmites cover produce significantly fewer viable hatchlings than those in Phragmites-free areas. This directly links Phragmites density to reduced nesting success, which is exactly what the ecologist''s hypothesis predicts. The finding about Phragmites growing faster in higher-salinity marshes addresses the plant''s growth conditions, not its effect on terrapins. The observation about a longer nesting season in Georgia compared to mid-Atlantic states concerns geographic variation in terrapin behavior, unrelated to the impact of Phragmites. The report that other invasive species are spreading through coastal wetlands is about general invasive species trends and does not address the specific Phragmites-terrapin relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NMJHYQ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "currency" most nearly mean?', E'Among historians of medieval trade, the thesis that guild monopolies stifled innovation has long held currency. However, recent archaeological evidence from thirteenth-century Flemish workshops suggests that guild structures actually fostered experimentation by providing artisans with stable markets and predictable demand, conditions that reduced the financial risk of trying novel techniques.', $lyceon_json$[{"key":"A","text":"money"},{"key":"B","text":"acceptance"},{"key":"C","text":"novelty"},{"key":"D","text":"controversy"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "acceptance." The phrase "held currency" in this context means the thesis has been widely accepted or believed among historians. "Money" reflects the most common definition of "currency" but is nonsensical when applied to an academic thesis holding something. "Novelty" means newness or originality, but the passage describes the thesis as having "long held" this quality, suggesting endurance rather than freshness. "Controversy" implies active dispute, but the passage presents the thesis as an established view only now being challenged by new evidence, not as something that has always been contentious.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NVOFO3', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "dispersed" most nearly mean?', E'When the unexpected rainstorm struck the outdoor festival, the crowd quickly dispersed, with attendees seeking shelter under awnings, in nearby shops, and beneath the broad canopies of oak trees lining the perimeter of the park.', $lyceon_json$[{"key":"A","text":"scattered"},{"key":"B","text":"assembled"},{"key":"C","text":"performed"},{"key":"D","text":"complained"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "scattered." The passage describes people moving away in different directions to find shelter, which matches the meaning of scattering. "Assembled" means the opposite — gathering together — which contradicts the movement away described in the passage. "Performed" refers to carrying out an action or entertaining, which has no connection to the crowd''s movement. "Complained" refers to expressing dissatisfaction, which is unrelated to the physical action of leaving.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RI5X5R', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the passage as a whole?', E'The fruit fly Drosophila melanogaster has long served as a model organism for genetic research, in part because its short generation time allows scientists to observe hereditary changes across dozens of generations within a single year. Studies using Drosophila have contributed to foundational discoveries about chromosomal inheritance, gene linkage, and mutation rates.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SRH7H6', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing an article about urban beekeeping, a student wants to present a contrast between the potential benefits and the challenges of maintaining hives in cities. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SXKXFT', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'In a 2021 study of linguistic code-switching, sociolinguist Marta Vidal-Covas analyzed recordings of bilingual Spanish-Catalan speakers in Barcelona during workplace meetings. She found that speakers shifted to Catalan most frequently when discussing topics related to regional identity or local traditions, even when the meeting''s default language was Spanish. Vidal-Covas interpreted this pattern as evidence that ________', $lyceon_json$[{"key":"A","text":"bilingual speakers' language choices during conversation are influenced by the cultural associations they attach to each language, not solely by practical communicative needs."},{"key":"B","text":"Catalan is gradually replacing Spanish as the primary language of professional communication in Barcelona."},{"key":"C","text":"workplace meetings conducted entirely in Catalan are more productive than those conducted in Spanish."},{"key":"D","text":"speakers who code-switch frequently tend to have lower proficiency in both of their languages than speakers who do not code-switch."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that bilingual speakers'' language choices are influenced by the cultural associations they attach to each language, not solely by practical communicative needs. The passage describes speakers switching to Catalan specifically for topics tied to regional identity, which supports the inference that cultural associations drive language selection in those moments. The suggestion that Catalan is replacing Spanish as the primary professional language goes far beyond the passage, which describes selective switching, not wholesale language replacement. The claim about productivity in Catalan-only meetings introduces a comparison the passage never makes. The assertion that frequent code-switchers have lower proficiency contradicts the general understanding of code-switching and is unsupported by the passage, which presents no information about speakers'' proficiency levels.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TF07Q4', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economists studying the adoption of solar energy in rural Senegal observed an unexpected pattern. Villages that received government-subsidized solar panel installations in 2017 initially showed strong adoption rates, with over 80 percent of households using the panels within six months. By 2021, however, usage had dropped to 34 percent in the subsidized villages. Meanwhile, in neighboring villages where a microloan program allowed residents to purchase panels at market price with low-interest financing, usage rates held steady at 71 percent over the same period. The economists suggested that this disparity most likely arose because ________', $lyceon_json$[{"key":"A","text":"the subsidized panels were manufactured by a different company and were therefore less durable than those available through the microloan program., based on the information presented"},{"key":"B","text":"households that invested their own financial resources in the panels developed a stronger sense of ownership and were more motivated to maintain and continue using them."},{"key":"C","text":"solar energy is generally unsuitable for the climate conditions found in rural Senegal."},{"key":"D","text":"the government subsidy program was designed primarily to benefit urban households rather than rural communities."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is that households investing their own resources developed a stronger sense of ownership and were more motivated to maintain and use the panels. This inference logically follows from the passage''s contrast between free subsidized panels (declining use) and financed panels requiring personal investment (sustained use), aligning with the economic principle that personal financial commitment increases perceived value and engagement. The suggestion that subsidized panels were less durable introduces an external factor the passage never mentions; the passage frames the comparison as one of acquisition method, not product quality. The claim that solar energy is unsuitable for rural Senegal''s climate contradicts the passage''s evidence that both groups initially used the panels successfully. The assertion that the subsidy targeted urban households is unsupported by the passage, which specifically describes the program operating in rural villages.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TGO8B1', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Linguist Ramona Suarez contends that the rapid decline of indigenous languages in South America is driven primarily by economic pressures. As rural communities integrate into national economies, younger generations increasingly adopt dominant languages to access employment, education, and government services, viewing their ancestral tongues as obstacles to economic mobility.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TJML65', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in the overall text?', E'In the mid-twentieth century, ecologists generally viewed forest fires as purely destructive events that should be suppressed whenever possible. This perspective guided decades of fire management policy across North America, resulting in aggressive suppression campaigns that sought to extinguish wildfires before they could spread.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VSGACD', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'When Swedish chemist Svante Arrhenius first proposed in 1896 that carbon dioxide emissions could warm the planet, his contemporaries largely dismissed the idea as irrelevant — the quantities involved seemed too small to matter. For decades, the hypothesis attracted little serious investigation. It was not until the 1950s, when oceanographer Roger Revelle demonstrated that the ocean could not absorb industrial carbon dioxide as rapidly as previously assumed, that the scientific community began to reconsider Arrhenius''s original insight.', $lyceon_json$[{"key":"A","text":"It presents an early scientific idea, describes its initial reception, and explains what prompted renewed interest in it."},{"key":"B","text":"It contrasts two scientists' opposing theories and argues that one was ultimately proven correct."},{"key":"C","text":"It describes a significant scientific discovery in detail and then lists the specific practical applications that directly resulted from it."},{"key":"D","text":"It introduces a controversy within the scientific community and proposes a resolution to it."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating the text presents an early idea, describes its reception, and explains what prompted renewed interest. The passage follows a clear chronological arc: Arrhenius''s 1896 proposal, its dismissal by contemporaries, decades of neglect, and then Revelle''s work in the 1950s prompting reconsideration. The choice about contrasting opposing theories is wrong because Revelle did not oppose Arrhenius; rather, his findings supported renewed attention to Arrhenius''s hypothesis. The choice about practical applications is inaccurate because the passage discusses scientific reception, not technological or practical outcomes. The choice describing a controversy and resolution mischaracterizes the passage, which depicts gradual neglect followed by renewed interest, not an active dispute requiring resolution.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W9E0I1', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing a report for a geography class, a student wants to emphasize the economic importance of the Suez Canal. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WXRHRX', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "tempered" most nearly mean?', E'The glassblower''s enthusiasm for experimentation was tempered by decades of experience; she knew precisely which innovations were worth pursuing and which would compromise the structural integrity of her pieces. This balance between creative ambition and practical knowledge had earned her a reputation as one of the most reliable artisans in the region.', $lyceon_json$[{"key":"A","text":"heated"},{"key":"B","text":"moderated"},{"key":"C","text":"provoked"},{"key":"D","text":"eliminated"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "moderated." The passage describes a balance between enthusiasm and experience, indicating that her eagerness was restrained or regulated — not removed — by her knowledge. "Heated" relates to a different sense of "temper" involving raising temperature, which does not fit the context of balancing enthusiasm with caution. "Provoked" means to incite or stimulate, which is the opposite of the restraining effect described. "Eliminated" is too extreme; the passage emphasizes balance, meaning her enthusiasm still existed but was kept in check.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XKI9A9', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The marine biologist Kendra Okafor has spent over a decade studying bioluminescent organisms in the Mariana _______ her research has revealed that certain species of jellyfish produce light in wavelengths previously unrecorded by scientists.', $lyceon_json$[{"key":"A","text":"Trench, and"},{"key":"B","text":"Trench and"},{"key":"C","text":"Trench. And"},{"key":"D","text":"Trench, but"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses a comma followed by the coordinating conjunction "and" to join two independent clauses, which is the standard method for connecting related ideas of equal grammatical weight. The choice omitting the comma before "and" fails to properly punctuate the junction of two independent clauses. The choice using a period before "And" creates an unnecessary sentence fragment beginning with a conjunction. The choice using "but" introduces an inappropriate contrast, since the second clause extends the first rather than contradicting it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z1NU1B', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Gothenburg recently examined the nesting behavior of the Eurasian magpie in urban environments. They found that magpies in cities consistently incorporated human-made materials, such as plastic strips and wire fragments, into their nests. Despite this unconventional construction, the nests were structurally comparable to those built entirely from natural materials. The researchers concluded that urban magpies have adapted their building techniques to exploit locally abundant resources without compromising nest integrity.', $lyceon_json$[{"key":"A","text":"Magpie populations in cities are declining because natural nesting materials are increasingly scarce."},{"key":"B","text":"Urban magpies have successfully adapted their nest-building practices to include human-made materials while maintaining structural quality."},{"key":"C","text":"The Eurasian magpie is the only bird species that uses synthetic materials in nest construction."},{"key":"D","text":"Researchers at the University of Gothenburg specialize in studying how pollution affects bird behavior."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is that urban magpies have successfully adapted their nest-building practices to include human-made materials while maintaining structural quality. This directly captures the passage''s central finding: magpies use synthetic materials yet produce structurally sound nests. The claim that magpie populations are declining overstates the passage, which never mentions population decline. The assertion that the Eurasian magpie is the only species using synthetic materials is unsupported, as the passage discusses only this one species without making comparative claims. The suggestion that the researchers specialize in pollution studies mischaracterizes their focus, which is nesting behavior, not pollution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZS3GCX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every autumn, the community garden on Oleander Street _______ volunteers from across the neighborhood who help harvest root vegetables and prepare the soil for winter dormancy.', $lyceon_json$[{"key":"A","text":"attract"},{"key":"B","text":"attracts"},{"key":"C","text":"have attracted"},{"key":"D","text":"are attracting"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "the community garden," which is singular. The correct choice uses the singular present-tense verb "attracts" to agree with this singular subject. The choice "attract" is a plural verb form that does not agree with the singular subject. The choice "have attracted" uses a plural auxiliary ("have" rather than "has") and shifts to the present perfect tense without justification, since the time marker "every autumn" indicates a habitual present action. The choice "are attracting" similarly uses a plural auxiliary and shifts to the present progressive, which conflicts with the habitual meaning conveyed by "every autumn."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-01"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-01","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZY2M0I', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Nutritionist Elara Voss argues that widespread adoption of vertical farming in urban areas would significantly reduce food transportation costs and carbon emissions, since produce would be grown within the same metropolitan regions where it is consumed.
